const summary = $input.first().json || {};
const counts = summary.counts || {};
const items = Array.isArray(summary.highPriorityItems) ? summary.highPriorityItems : [];
const countLabels = [
  ['paidLeadsReadyForDispatch', 'Paid leads ready for dispatch'],
  ['pilotDispatchesToCreate', 'Pilot dispatches to create'],
  ['dispatchesNeedingAction', 'Dispatches needing action'],
  ['dispatchesOlderThanTwoDays', 'Dispatches older than 2 days'],
  ['dispatchesOlderThanSevenDays', 'Dispatches older than 7 days'],
  ['visitsNeedingReports', 'Visits needing reports'],
  ['visitReportsNeedingReview', 'Visit reports needing review'],
  ['marketingAwaitingReview', 'Marketing awaiting review'],
  ['marketingOverdue', 'Marketing overdue'],
  ['systemHealthAlerts', 'System health alerts']
];
const generatedAt = summary.generatedAt ? new Date(summary.generatedAt) : new Date();
const summaryDate = summary.summaryDate || generatedAt.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' });
const totalOpenSignals = countLabels.reduce((total, [key]) => total + Number(counts[key] || 0), 0);
const severityRank = { Critical: 3, Warning: 2, Review: 1 };
const topItems = [...items]
  .sort((a, b) => (severityRank[b.severity] || 0) - (severityRank[a.severity] || 0))
  .slice(0, 20);
const countLines = countLabels
  .map(([key, label]) => `${label}: ${Number(counts[key] || 0)}`)
  .join('\n');
const itemLines = topItems.length
  ? topItems.map((item, index) => {
      const status = item.status ? ` | Status: ${item.status}` : '';
      const dueDate = item.dueDate ? ` | Due: ${item.dueDate}` : '';
      const url = item.url ? `\n   Open: ${item.url}` : '';
      return `${index + 1}. [${item.severity || 'Review'}] ${item.category || 'General'} - ${item.title || 'Untitled'}${status}${dueDate}\n   Next: ${item.nextAction || 'Review in Jiva Farm OS.'}${url}`;
    }).join('\n\n')
  : 'No high-priority items returned by Jiva today.';
const subject = `Jiva Daily Management Digest - ${summaryDate} - ${totalOpenSignals} open signals`;
const plainText = `Jiva Daily Management Digest\nDate: ${summaryDate}\nGenerated: ${generatedAt.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })}\nEnvironment: ${summary.appEnvironment || 'unknown'}\n\nOperating Counts\n${countLines}\n\nTop Priority Items\n${itemLines}\n\nOpen Jiva Farm OS: https://www.jivawater.org/my-pending-work`;
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<div style='font-family: Arial, sans-serif; color: #111827; line-height: 1.45;'><h2 style='margin-bottom: 4px;'>Jiva Daily Management Digest</h2><p style='margin-top: 0;'>${escapeHtml(summaryDate)} · ${totalOpenSignals} open signals</p><pre style='white-space: pre-wrap; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; background: #f8fafc; border: 1px solid #e5e7eb; border-radius: 8px; padding: 16px;'>${escapeHtml(plainText)}</pre></div>`;
return [{ json: { subject, plainText, markdown: plainText, html, summaryDate, totalOpenSignals, counts, highPriorityItems: topItems, rawSummary: summary } }];
